import{_ as e,c as p,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"易纂言卷八","description":"易纂言 - 易纂言卷八","frontmatter":{"title":"易纂言卷八","description":"易纂言 - 易纂言卷八"},"headers":[],"relativePath":"zh/classics/zuanyan/009.md","filePath":"zh/classics/zuanyan/009.md"}'),n={name:"zh/classics/zuanyan/009.md"};function r(c,a,_,i,o,l){return t(),p("div",null,[...a[0]||(a[0]=[s('<h1 id="易纂言卷八" tabindex="-1">易纂言卷八 <a class="header-anchor" href="#易纂言卷八" aria-label="Permalink to “易纂言卷八”">​</a></h1><p>钦定四库全书</p><p>元吴澄撰</p><p>八卦成列，象在其中矣。因而重之，爻在其中矣。刚柔相推，变在其中矣；系辞焉而命之，动在其中矣。吉凶悔吝者，生乎动者也。 八卦成列，谓乾一、兑二、离三、震四、巽五、坎六、艮七、坤八相次也。象，谓文王所名之卦。在其中者，谓包含于其中也。因而重之，谓因八卦而重之为六十四也。爻，谓周公所系之辞。变者，蓍之变。命，犹名也。动者，人之动。已有八卦之时，犹未有六十四卦之名也。已有重卦之时，犹未有三百八十四爻之辞也。刚柔二画，虽能相推变化，然蓍未变则未有九、六也。系辞虽名为吉为凶，然人未动则未有吉、凶也。虽未有之，而其理已具，故曰在其中矣。吉凶悔吝，因人之动而后有。周子曰：吉一而已，动可不慎乎？澄谓：「此承前篇卒章，言蓍卦之象、辞、变、占。曰在其中者凡四：一象、二爻、三变、四动。爻者，辞也。动则有吉凶悔吝之占焉。前篇动者尚其变，而此以动属占者，动因变而得占也。 刚柔者，立本者也；变通者，趣时者也。」 刚柔之画，其体一定，如木本之植立，因蓍之变，其用相通，随时所遇，趣而就之，刚或化柔，柔或化刚也。此承「刚柔相推，变在其中」之语，而言蓍之变。 吉凶者，贞胜者也。天地之道，贞观者也；日月之道，贞明者也。天下之动，贞夫一者也。 贞，谓正主之也。吉凶二占，正主于一胜。吉胜则无凶，凶胜则无吉，非如悔吝之可吉可凶也。观，犹示也。因吉凶之正主于胜，遂言天地之文理正主于示人；日月之往来正主于明照；而天下人事之动，则正主于一，而不可以二。不吉则凶，不凶则吉，所谓贞胜也。此承「吉凶悔吝生乎动」之语，而言蓍之占。 夫乾，确然示人易矣。夫坤，𬯎然示人简矣。爻也者，效此者也。象也者，像此者也。 「乾」谓天，「坤」谓地，非卦名也。确，刚健貌。𬯎，柔顺貌。天地之「贞观」者，天则刚健而示人以易，地则柔顺而示人以简。周公之爻，文王之象，则亦效像天地而示人以易简也。此承「象在其中」、「爻在其中」之语，而言卦之爻与象。 爻象动乎内，吉凶见乎外，功业见乎变，圣人之情见乎辞。 内，谓易书之内；外，谓易书之外。爻象无非示人以动而趋吉之理，然其动在乎易书之内，实未尝有动之事也。人之动如是而吉，不如是而凶，则著见于人事，而在乎易书之外矣。以蓍之变，决其嫌疑，定其犹豫，而勇于趋事，则功业之成，皆因蓍之变而著见也。以上言辞、言象、言吉凶之占、言见乎变，四者备矣。而又以一句结之，谓圣人与民同患之情，皆于易而著见，此辞字兼彖爻言也。圣人之道四，而独归重于辞，盖此篇为系辞之传故也。</p><p>传六之一章，凡百四十六字。趣，立树切。胜，绳证切。观，古唤切。夫，音扶。确，苦各切。易，以豉切。𬯎，同捸切。见，经电切。诸本皆至下章「禁民为非曰义」为一章。今案：「天地之大德曰生」与此文不相属，当为下章之首。属，之欲切。 天地之大德曰生，圣人之大宝曰位。何以守位曰人，何以聚人曰财。理财正辞，禁民为非曰义。 生生不已者，天地之大德。然天地生物生人，又生与天地合德之圣人，命之居君师之位，为人物之主，而后能使天地之所生得以各遂其生也。苟或但有其德而无其位，则亦不能相天地而遂人物之生，故位为圣人之大宝。大宝，谓大可贵重。守，谓保有之，必得众人之归向，乃能保有君师之位。聚，谓养之而使蕃盛众多。财者，天地所生之物，以养天地所生之人，故聚人以财也。理，谓以道取而用之。理财必正其辞，谓取其所当取可取，言之而无悖无愧者。禁，谓防制之。盖财者，民之所同欲，争盗之所由起，必设法令以禁其为非，使之不敢争，不敢盗。义者，事理之宜。理财之所宜理，禁民之所不宜为，夫是之谓义。以下言五圣人之制作，皆聚人理财之事。 古者包牺氏之王天下也，仰则观象于天，俯则观法于地，观鸟兽之文与地之宜，近取诸身，远取诸物，于是始作八卦，以通神明之德，以类万物之情。 包牺氏，大昊也。气之有文者曰象，形之有理者曰法。汉书艺文志相地为形法家。天有雷、风、日、月。雷风，气也。日月，象也。言象可以兼气。地有水、火、山、泽，水火，质也。山泽，形也。言形可以兼质。鸟兽之文，谓动物。地之宜，谓植物。身，就人而言。物，该服食器用而言。通，同之也。神明，天地之气象形质，妙而叵测，显而可见者也。德，若「健」、「顺」、「动」、「入」、「陷」、「丽」、「止」、「说」，及鼓之，散之，「润之」，「烜之」之属，类似之也。「万物」，凡动植人器皆是。「情」，犹言其意义也。羲皇观于天地，观于动植，近取远取，洞见两间自然之易，乃画奇耦二画，交互成八卦以象之。而天地万物悉不外是。故与其德同，而与其情无不相似也。天开地辟之后，不知其几万年矣。而洪荒朴略，未有文字。至羲皇始画八卦，实肇人文之端，故将言制作之事，而首言此也。 作结绳而为网罟，以佃以渔，盖取诸离。 以散丝散麻绊紧而合之曰「结」，结之以为绳也。网以取兽曰「佃」。罟以取鱼曰「渔」。或曰「网」罟通用，上古之时，已有结绳矣。作之而为网罟者，羲皇也。或曰结绳而治，亦自羲皇始。「结绳」、网罟二事，结绳以防欺诈，因以为网罟而佃渔也。二说未详孰是。「盖」者，不敢决定之辞。圣人非必模仿此卦以制此器，其象相类尔。又此时未有重卦之名，借后本所立卦名言之，故不决定其辞，而曰「盖」。「离」谓「重离」。「重离」两目相承，边实中虚，为物所丽，结绳网罟之象。人无爪牙，不能敌兽之猛。羲皇以前，兽每食人。既有网罟之后，人始能取鱼兽以食之，而免为兽所食。大哉，圣人之仁乎！ 包牺氏没，神农氏作，斲木为耜，揉木为耒，耒耨之地，以教天下，盖取诸益。 神农氏，炎帝也。斲，谓削而锐之。耜者，耒首。揉，谓揉而曲之。耒者，耜柄。教天下者，古未有粒食，神农始教民稼穑者也。益之二三四，互坤，地也。上巽二阳，象耒之自地上而入。下震一阳，象耜之在地下而动也。 日中为市，致天下之民，聚天下之货，交易而退，各得其所，盖取诸噬嗑。 案，周官有三市，此独言日中者，或创市之初，惟用日中，后王乃增朝夕二市与？噬嗑上离，日中之象。离中虚，可藏货，市之象。震动而前，致民之象。震二柔画，为民。离明，万物相见，聚货之象。离二刚画，富实货也。一刚一柔相间，有相交相易之象。退，谓交易既毕而归其家。各得其所，谓以其所有，易其所无，而归各得以遂其愿，济其所用也。 神农氏没，黄帝、尧、舜氏作，通其变，使民不倦；神而化之，使民宜之。易穷则变，变则通，通则久。 黄帝，轩辕氏。尧，陶唐氏。舜，有虞氏也。「通其变」者，通其所当变之事，使不至于穷也。变而无迹曰化。上古之时，民与禽兽无异，有网罟而鲜食者，有耒耜而得艰食者。艰鲜既奏，而又为市以质，迁其有无，则与禽兽稍异矣。然民用之未备者犹多也。风气渐开，不可如朴略之世，此穷而当变也，变之则通而不穷矣。其能使民喜乐不倦者，以其通之之道神妙不测，变而不见其迹，使于民而民皆宜利之故尔。凡易之道，穷则必变而通之，然后可以久而无弊。黄帝、尧、舜之通其变者，易之道也。九事皆黄帝时，而并言尧、舜者，肇始于黄帝，而极备于尧、舜也。不言少昊、颛顼、帝喾者，承黄帝之后，因之而无所损益也。 黄帝、尧、舜垂衣裳而天下治，盖取诸乾坤。 「衣」，上体之服。「裳」，下体之服。上古以禽兽、羽毛、草木华叶蔽其体，至此始以丝麻为衣裳也。上衣下裳，如天尊地卑，上下分定，故天下治。乾画奇，象衣之缝合为一。坤画耦，象裳之前后殊为二。 刳木为舟，剡木为楫，舟楫之利，以济不通，盖取诸涣。 刳木者，刳空其中为舟以浮水。剡木者，剡薄其端为楫以运舟。水所阻隔，道路不通，则以舟楫渡而济之也。「涣」巽木，在「坎」水之上。二三四五上，舟虚之象。初耦二「楫」，运于舟后之象。 服牛乘马，引重致远，以利天下，盖取诸随。 服者，以轭加其项，而使之引重。载乘者，以衡加其背，而使之致达道。随下震自坤而变坤为牛，一奇画在后者，象所引之重物也。上兑自乾而变，乾为马，一耦在前者，象前路开通无碍，而可以致远也。 重门击柝，以待暴客，盖取诸豫。 郭门、城门为重门。「击拆」，所以警夜而防奸盗也。暴客，谓奸盗。豫前二耦画，重门之象。九四一奇画而动，体击柝于门内之象。坤三画在下，民安居于内，而无暴客侵陵之象。 断木为杵，掘地为臼，臼杵之利，万民以济，盖取诸小过。 杵以舂，臼以容，用之捣去粟壳而得米，其利便万民，亦犹渡水之得济也。小过横而观之，中二奇画象木杵，内外四耦画象地臼。 弦木为弧，剡木为矢，弧矢之利，以威天下，盖取诸睽。 弧，木弓也。兵器不一，弓矢所及者远，为长兵威天下者，示有警备而使之畏也。坎象弧者，中弣强而上下两弰弱也。离象天者，前镞后栝实、中笴虚也。暌三四五互坎，弧象；二三四互离，及上体之离，皆矢象。 上古穴居而野处，后世圣人易之以宫室，上栋下宇，以待风雨，盖取诸大壮。 上古，谓黄帝以前。穴居土中，营窟也。野处木杪，橧巢也。「后世圣人」，谓黄帝、尧、舜也。外垣四同曰「宫」，户牖之内曰「室」。「栋」，檩之上隆者。「宇」，椽之下垂者。有栋宇而成屋，则可以障风蔽雨。大壮下四刚，栋承上而隆之象；上二柔，宇覆下而垂之象。 古之葬者，厚衣之以薪，葬之中野，不封不树，丧期无数，后世圣人易之以棺椁，盖取诸大过。 「厚衣之以薪」，谓以薪承藉其下而置尸焉，复以薪盖覆于其上也。「中野」，野中也。「不封」，不封土为坟也。「不树」，不树木以识也。「丧期无数」，哀尽则止，无卒哭、祔、练、祥、禫之日数也。「棺」，内棺；「椁」，外棺也。凡奇画为长，耦画为短。大过中四长画；九二，棺底木也；九三、九四，棺两傍木也；九五，棺盖木也。初、上二短画，上六，棺前端木也；初六，棺后端木也。 上古结绳而治，后世圣人易之以书契，百官以治，万民以察，盖取诸夬。 「结绳」，说者谓民淳事简，结绳以为信，大事大其绳，小事小其绳，以识别也。「书」，以刀笔画木简为文字也。「契」，以木刻一、二、三、四之画，而中分之，各执其一，合之以为信也。「契」者，书之始也。契惟以画记数而已，书则有指事、象形之变，有文字则可以治百官之事，察万民之情矣。书契自一画、二画、三画、四画始，至五画则为又，盖至五而穷也，穷则变。夬有五奇画，象书契之一、二、三、四、五，至六则变矣。故上画耦者，奇之变也，又象契之上端分为二之处。十三卦之制作，自画卦而始，至书契而终。盖万世文字之祖，肇于画卦，而备于书契也。 是故易者，象也。象也者，象也。 此章之首第一节，总叙以起下文。自「包牺」至「书契」十四节，言制作之事，而以是故总结之。谓易卦皆器物之象，象者，像似之义。圣人制器，皆与卦象合也。 彖者，材也。爻也者，效天下之动者也。 既结一章之意矣，因象而及于辞，谓文王彖辞以六画之象而论一卦之材质，周公爻辞以一画之象而效人所作为之事。 是故吉凶生而悔吝著也。 又以是故结上文二句，谓彖、爻如此，故生出吉凶而使人趋避，著明悔吝而使人警悟也。</p><p>传六之二章，凡四百二十九字。「守位曰人」，旧本「人」作「仁」。陆氏曰：王肃、卞伯、王、桓玄、明僧绍作人。耒耜，旧本「耜」作「耨」。晁氏曰：「王昭素云：诸本或作耜，乃合上文。」澄谓传写者讹右傍以字为「辱」也。今正之。「通则久」下，旧本有「是以自天祐之，吉无不利」十字。系文言传释大有上九爻辞，错简重出。「以济不通」下，旧本有「致远以利天下」六字。陆氏曰：「一本无。」今案：此六字见下文，羡文重出也。包，白交切。王于况切。柝天作切。厚衣于既切。注相天地息亮切。后「相地」同。夫是音扶。叵平可切。止说音曰。烜沉远切。合之音合。二市与音余。相间居限切。喜乐音洛。分定封问切。重载亲采切。舂黍容切。弣封古切。弰新巢切。镞子本切。笴见汗切。僧音曾。垣音袁。檩林锦切。藉晴夜切。置音至。复以扶后切。覆孚后切。以识音志。后「识别」同。潭汀坎切。别彼列切。 阳卦多阴，阴卦多阳，其故何也？阳卦奇，阴卦耦。其德行何也？阳一君而二民，君子之道也；阴二君而一民，小人之道也。 阳卦，震、坎、艮也，皆一阳二阴，阴多于阳。阴卦，巽、离、兑也，皆一阴二阳，阳多于阴。故者，其迹之粗；德行者，其理之精。先粗后精，两设问而两答之也。阳卦数奇多阴，则一奇二偶，合成五数；阴卦数耦多阳，则一耦二奇，合成四数。数分奇耦，以答其故之问。阳画为君，阴画为民。阳卦一君统二民，寡能治众，主必致一，得理之正，为君子之道。阴卦一民事二君，土无二王，物不两大，非理之正，为小人之道。道分君子小人，以答其德行之问。 乾坤，其易之门邪？乾，阳物也。坤，阴物也。阴阳合德，而刚柔有体，以体天地之撰，以通神明之德。 上文既言六子之卦，此乃言六子自乾坤而生也。易，谓六子，以奇耦相易而成卦，故曰「易」。乾坤者，六子之所从出，故曰「门」。「物」，犹言画也。射礼：画于地者亦曰物。乾三画皆阳，故曰「阳物」。坤三画皆阴，故曰「阴物」。乾，阳之德；坤，阴之德，交互相合，以生六子。而震、坎、艮，有一刚二柔之体，巽、离、兑，有一柔二刚之体。此八卦者，与天地神明一也，故曰「体」曰「通」。「体」，谓以之为体也。「撰」，犹言所为也。「体天地之撰」，以卦象言。「通神明之德」，以卦德言。 其称名也，杂而不越，于稽其类，其衰世之意邪？ 此又言六十四卦自八卦而生也。「名」，谓重卦之名。「离」，谓不一。「越」，过也。「于」，叹辞。「稽」，推考也。文王所称五十六卦之名，虽其义不一，而皆不过自八卦中出。叹其推考重卦两体，与八卦所象相类而立名之意。见其遭遇衰世，忧患危惧，是以推考如是其精微也。 夫易彰往而察来，而微显阐幽，开而当名辨物，正言断辞，则备矣。 以上三节，首言六卦之体，次言六卦本乎二卦而为八，又言重卦本乎八卦而为六十四。此以下总上三节而言文王之彖辞。「彰往」，即「藏往」也，谓明于天之道，而彰明已往之理。「察来」，即「知来」也，谓察于民之故，而察知未来之事。「微显」，即「神德行」也，谓以人事之显，而本之于天道，所以微其显。「阐」者，阐而显之也。「阐幽」，即「显道」也，谓以天道之幽，而用之于人事，所以阐其幽。上篇之「藏往」、「知来」、「显道」、「神德行」，兼蓍而言，此则专以卦而言也。开明名卦之意，而使当其名。辨别阴阳之物，而正言其占。「夫易」以下诸义，自文王断以彖辞之后，则皆具备矣。朱子曰：「而微显」，恐当作「微显而」。「开而」之「而」，亦疑有误。 其称名也小，其取类也大。其旨远，其辞文，其言曲而中，其事肆而隐。因贰以济民行，以明失得之报。 「小」，谓其义专而狭。「大」，谓其义泛而广。「旨」，意也。「文」，谓修节而不质直。「曲」，谓一偏而不该徧。「中」，如居中而四外皆通。「肆」，谓纵而不拘。「隐」，谓晦而不显。彖首所称卦名，如上云下雷，则名为屯；上山下泉，则名为蒙。但就本卦二体之象而生名，故曰小。彖中所取象类，如类动物，则有虎尾、豚鱼、飞鸟、小孤之属；类用物，则有盥荐、二簋、羸瓶、匕鬯之属。泛及天下诸物之形而比类，故曰大。称名之义虽小，而其旨则远，谓推索而无穷尽也。取类之义虽大，而其辞则文，谓假托而不质言也。小者虽偏曲而局于一方，然旨之远则中而可旁通也。大者虽纵肆而徧于诸物，然辞之文则隐而不显露也。贰谓疑而不决，用筮以占，而彖辞为决所疑，则行事之果如渡水之得济，故曰「济民行民于行事之失得未能明也」。以彖辞而知如此为得而行之则有吉报，如彼为失而行之则有凶报，故曰「明失得之报」。或谓此一节盖论彖、爻。夫取类之大，辞之文，事之肆而隐，爻辞亦然，而此则专为彖辞言也。</p><p>传六之三章，凡百六十二字。「小人之道也」下，旧本有文言传错简，释咸九四、困六三、解上六、噬嗑初六、上六、否九五、鼎九四、豫六二、复初九、损六三、益上九爻辞十一节间隔之，故与乾坤其易之门不相属，遂于「乾坤」上加「子曰」字，而分为别章。今定错简归文言传，删去「子曰」字，而此章复合为一。德行，下孟切，后「民行」同。撰，士免切。于，音乌。夫，音扶。断，东乱切。中，如字。注索，悉革切。为决，云伪切，后「为彖」同。夫微显，音扶。 易之兴也，其于中古乎？作易者，其有忧患乎？ 中古，谓文王时。羲皇之易有画而已，三画之卦虽有名，而六画之卦未有名，文王始名六画之卦而系之以辞，易道几微而至此复兴也。卦名及辞皆前所未有，故不云述而云作。作易在羑里时，故云其有忧患乎？盖于其名卦而知其有忧患也。下文举九卦之名，以见其忧患之意。 是故履，德之基也；谦，德之柄也；复，德之本也；恒，德之固也；损，德之修也；益，德之裕也；困，德之辨也；井，德之地也；巽，德之制也。 履，践行也。基，如筑土之下址，积累之所始也。谦，恭让也。柄，所执持者也。复，反也，孟子谓君子必自反也，行有不得者，反求诸已，如木之反也。本，归根也。恒，常久也。固，谓常守而不变也。损者，减损，谓消除其私欲也。修，谓完补其阙也。益者，增益，谓充长其善端也。裕如，加厚其衣也。困，阨穷也。辨者，识之明，孟子谓人之德慧术智存乎疢疾，因身之困而心识开明也。井不动而及物之惠普徧，犹地之静而成物之功广博。巽者，柔顺卑下以入，则无处而不可入，如利刀之裁制布帛，随其长短而裁之，无不如意也。始之以实践，继之以自谦，人不我是而自反，已之所守必有常，损其不善益其善，虽处困而识愈明，身不可动而不忘及物，柔顺卑下，无入而不自得。此九字之义，皆处忧患之道也。 履和而至；谦尊而光；复小而辨于物；恒杂而不厌；损先难而后易；益长裕而不设；困穷而通；井居其所而迁；巽称而隐。 上文初陈九卦之名，取其字义而已。此再陈，乃取卦义。项氏曰：「释卦之两体九句，皆以相反成文。」朱子曰：「如书之九德。」澄案：和谓兑之说，至谓乾之健。盖虽与物无乖，而行必造极也。乡原之阉然媚世，而不可入尧舜之道，则履之和而不至者。尊谓坤地之卑而尊之，使居艮上。光谓艮山虽下于坤，而自不失其为高。已处人下，疑若晦昩而不光。然谦则虽尊他人而已亦光也。小谓震。一阳之动。辨于物谓珅众阴之顺。一阳之复甚微，犹君子之自反，所操甚约也。然阳复于内虽微，而阴顺于外则众，犹君子一自反而横逆者皆顺，非明于接物不能也。「杂」谓其事不一，震雷之时复一鸣似之。「不厌」如言学不厌，巽风之无日不有似之。行事不一，而终终不厌倦，所以为恒也。「先难」谓方损之初，如浚兑泽于下，而畚土以上也。「后易」谓既损之后，如艮山之静止，而受土以成其高也。「长裕」谓日益。「设」谓施为之虚假，如设使、设或之说。揠苗而长之，其苗非实有长裕也，虚假所为尔。震雷之声，则实能助益巽风之势，而不虚假也。「穷」，谓兑泽涸于上。「通」谓坎水流于下。或谓彖传之险而说，亦穷而通之义。彼盖合上下二德，以释「困亨」，与此不同也。「居其所」，谓巽之二阳在下体，水之在井中者也。「迁」谓坎之一阳在上体，水之汲而上以及物者也。「称」，谓巽二阳在阴之前，二阳体钧，其重不偏，如称物之平。「隐」谓巽一阴入阳之内，为卦之主，以事二君，而人莫知其所以能入二阳之故。履、复、损、井，取义以下体为先。谦、恒、益、困，取义以上体为先。巽八纯重卦，但就一体取二义，而二体皆然。 履以和行，谦以制礼，复以自知，恒以一德，损以远害，益以兴利，困以寡怨，井以辩义，巽以行权。 此章三陈九卦，先后有浅深。初陈杂举卦名，而每字之下，先就人身言之，以明其字义，未及卦义也。再陈，乃于卦名之下，说上下二体之义；三陈，则卦字名，一字之中包含上文所说卦体二义，非专指卦名一言也。「以」，犹象传「君子以」之「以」，谓取此卦之义，用之于人事也。践行之履，在人为德之基，故名下兑上乾之义曰「履」。其义兑和而乾至，人则以此履卦之义而和行。和行，谓所行无乖忤也。恭让之谦，在人为德之柄，故名上坤下艮之卦曰「谦」。其义坤尊而艮光，人则以此谦卦之义而「制礼」。礼者，恭敬退让，自卑而尊人；制礼，谓制为仪则也。自反之复，在人为德之本，故名下震上坤之卦曰「复」。其义震小而辩于坤之物，人则以此复卦之义而自知。爱人不亲反其仁，治人不治反其智，礼人不答反其敬，惟自知反己，不责人之不亲、不治、不答也。常久之恒，在人为德之固，故名上震下巽之卦曰「恒」。其义震之雷杂，而巽之风不厌，人则以此恒卦之义而一德。一，谓终始如一也。减省之损，在人为德之修，故名下兑上艮之卦曰「损」。其义：先损兑之泽难，而后成艮之山易，人则以此损卦之义而远害。为不善者有害于已，减损其不善，所以远去其害也。增多之益，在人为德之裕，故名上巽下震之卦曰「益」。其义巽之风长裕，而震之类不设，人则以此益卦之义而兴利。为善者有利于已，增益其善，所以兴起其利也。阨穷之困，在人为德之辩，故名上兑下坎之卦曰「困」。其义兑穷而坎通，人则以此困卦之义而寡怨。知命安分者，虽阨穷患难而无怨，寡之以至于无也。掘地得泉之井，在人为德之地，故名下巽上坎之卦曰「井」。其义：巽居其所而坎迁，人则以此井卦之义而辩义。已之惠泽及人者，义也。柔顺卑下以入之巽，在人为德之制，故羲皇三画之卦名「巽」，文王名六画之重卦亦曰「巽」。其义：上中二阳宜称于外，而下之一阴隐伏于内，人则以此重巽之义而行权。行，谓不定在一处。权者，称锤，前却无定，以等物之轻重而取衡之平，时中是也。六十四卦，其可以处忧患者不止于九，夫子姑举其大槩尔。五十六重卦，举八卦，七之一也；纯卦举一卦，八之一也。</p><p>传六之四章，凡百四十五字。厌：因剑切。易：以豉切。长：知两切。称：充证切。行：下孟切。远：于愿切。注「充长」同上。疢：充震切。尤处：充许切，后一处同。乡原音愿。阉音淹。横逆：封孟切。时复：符后切。畚音本。以上时掌切，后「而上」同。揠音戛切。涸：曷各切。而说：音曰。减省所梗切。安分：奉问切。难：乃旦切。掘：群厥切。锤：程追切。 易之为书也不可远，为道也屡迁。 不可远，谓其书之利于民用，不可离去也。屡迁，谓其变易不一定也。 变动不居，周流六虚，上下无常，刚柔相易，不可为典要，唯变所适， 以卦变言也。变动，谓卦画更变移动，两易其位也。不居，不止定在一处也。周流，周徧流行也。六虚，卦之六位也。在上位者或降而下，在下位者或升而上，无有常处者，以刚柔二画之互相易也。典要，典籍中之契要，常而不可易者也。不可为典要，谓其易而不可常也。唯其变画之所之，适在何位尔。案：传之单言变者，谓蓍策之变；言变化者，谓卦画之变。唯变所适，非谓蓍策也。而亦单言变者，盖此言卦变之互易其位，非爻变之变化其画也。不可言化，故亦单言变。夫子于彖传已言卦变矣，而于此又言之。一体三画自相易者，「复」、「姤」、「临」、「遁」、大壮、「观」、「夬」、「剥」所变也。下体三画与上体三画互相易者，「泰」、「否」、「坎」、「离」、「震」、「艮」、「巽」、「兑」所变也。蔡氏曰：「此言易道之屡迁也。」 其出入以度，外内使知惧，又明于忧患与故，无有师保，如临父母。 「出入以度，外内知惧」，言人事之动，亦当如卦画之变也。出，谓升上。入，谓降下。外者，上也。内者，下也。卦画之出而外、入而内者，皆以其度，或一体自易，或二体互易。六子八辟之所变各二卦，泰、否二辟之所变各九卦，如度之分寸，各有界限，不可僭差。人事之或出或入，亦必如卦画之出入，以度其出入，动循礼法，使出而在外、入而在内之时，惕然知所畏惧。此圣人作易训人之意。使，谓圣人之使人如此也。凡人之出入，能明于圣人之忧患与民同之义，以慎乃事而守之严，虽无有师保显为之教戒，而畏惧不敢慢易，惕然一如父母之临其上也。蔡氏曰：「此言易书之不可远也。」 初率其辞而揆其方，既有典常，苟非其人，道不虚行。 「初」，始也。率，循也。辞，彖、爻之辞也。揆，度也。方，所向也。既，尽也。典常，典籍中所载之常法，一定而不可易者也。言人于用易之始，循易书之辞，而揆其处事之方，其道尽有常法，不可变易也。上言卦画之变，其道变而不常；此言彖爻之辞，其道常而不变也。苟，犹若也。其人，谓圣人。易之道虽如此，若非作易之圣人示此道以教人，则易之道不能无人而自行也。盖言易道之行于世者，皆圣人之功。蔡氏曰：此合书与道为言也。</p><p>传六之五章，凡八十三字。要，去声。度，如字。注并同注。离，艮智切。更变，音庚。一处、常处，充注切。辟，音壁。慢易，以豉切。度也，待洛切。处事，昌主切。 易之为书也，原始要终，以为质也。六爻相杂，唯其时物也。 要，如「要于路」之「要」，谓遮截其归宿之处。质，谓卦之体质。文王原卦义之始，要卦义之终，以为卦之体质，各名其卦而系彖辞也。爻之为言交也，六位之阴阳相杂而交错也。时，谓初、二、三、四、五、上之时。物，谓阳奇、阴耦二画之物。周公观六爻之交错，唯其六位之时，或是阳物，或是阴物，各因其义而系爻辞也。此章言六爻，而六爻统于彖，故先言彖。下文乃分说六爻也。 其初难知，其上易知，本末也。初辞拟之，卒成之终。 此言初、上二爻。侯氏果曰：初则事微，故难知；上则事彰，故易知。澄谓初如木下之本，上如木上之末。观木者，其下之本根难见，其上之枝叶易见也。项氏曰：初祸福未定，故其辞多拟议；上已睹其成，祸福判矣，故其辞多决定。澄案：终谓上爻、初爻之辞。「拟之」者，犹有商度。卒竟成完而言之者，终爻之辞也。「初」与「终」为对，「拟之」与「卒成之」为对，两句文法颠倒相互。 若夫杂物撰德，辩是与非，则非其中爻不备。 此言卦中四爻。中爻谓二、三、四、五也。朱子曰：先儒多解此为互体。胡氏一桂曰：「杂物」谓阴阳一物，自中四爻杂而互之，又自撰成两卦之德也。是与「非」，谓中与不中、当位与不当位也。内外卦既足以示人，复自互体而辩之，则是非益可见。澄谓内外既有二正体之卦，中四爻又成二互体之卦，然后其义愈无遗缺。非以此正体、互体并观，则其义犹有不备。正体则二为内卦之中，五为外卦之中；互体则三为内卦之中，四为外卦之中，故皆谓之中爻。 噫！亦要存亡吉凶，则居可知矣。知者观其彖辞，则思过半矣。 上文既分言初、上二爻及中四爻，此又总六爻言之。存亡者，阴阳之消息；吉凶者，事情之得失。居，犹坐也。要其存亡吉凶之所归，则六爻之义坐而可知矣。又谓知者能见事于未形，虽不观各爻之义，但观卦首之彖辞，则所思已得十分之五六矣。盖彖辞或论二体，或论主爻，或论卦变相易之爻，是以不待观六爻而已可见也。章首第一句言彖，第二句总言六爻，此一节又总言六爻，而后归重于彖，盖为结语，与章首起语相始终。下文则又更端而言中四爻也。 二与四，同功而异位，其善不同，二多誉，四多惧，近也。柔之为道，不利远者，其要无咎，其用柔中也。 二与四同是阴位，若皆以柔居之，则六二、六四，同是以柔居阴，故曰「同功」。然其位则有远近之异。五者，一卦之尊位，故远近皆自五而言。二与五应为远，四与五比为近。以位之远近有异，而其善亦不同。远者，意气舒展而多誉；近者，势分逼迫而多惧。多者，谓不尽然，而若此者众尔。「近也」二字，释「四」。「多惧」，谓四之所以惧，不能如二之誉者，盖迫近尊位，不得自安故也。「柔之为道」以下，释「二」。多誉。柔不能自立，近者有所依倚，远者宜若不利。二远于五，而其归得以无咎者，以其用柔而居下卦之中也。 三与五，同功而异位。三多凶，五多功，贵贱之等也。其柔危，其刚胜邪？ 三与五同是阳位，若皆以刚居之，则九三、九五同是以刚居阳，故曰「同功」。然其位则有贵贱之异。五，天子之位，为贵；三，诸侯之位，为贱。以位之贵贱有异，贱者刚居刚，为大过而多凶，贵者刚居刚为适宜而多功。「二多誉」、「四多惧」之上有「其善不同」一句，而「三多凶」、「五多功」之上无之者，誉惧虽不同，而皆可谓之善，凶则不可谓善矣，故不言也。等，谓两相比并而有品级。「贵贱之等也」，五字释「三多凶」，谓三之所以凶，不能如五之功者，盖贵贱有等，贱者不与贵者同，不宜以刚居刚故也。「其柔危」以下，释「五多功」。五为尊位，以柔居之，则不胜其任而危，惟刚居之，则能胜其任而有功也。</p><p>传六之六章，凡百四十四字。要，一遥切。后同。易知，以豉切。夫，音扶。撰，士免切。知者，音智。思，先次切。胜，音升。注摘度，待洛切。竟，音敬。复自，符后切。五比，皮二切。势分符问切。 易之为书也，广大悉备。 广，谓如地之无所不容；大，谓如天之无所不包。悉备，谓人物之理纤悉具备于其中。 有天道焉，有人道焉，有地道焉。 此言三画之卦。「天道」，谓上画象大覆于上。「人道」，谓中画象悉备于中。「地道」，谓下画象广载于下。 兼三才而两之，故六，六者非他也，三才之道也。 此言六画之卦。「兼」，犹言双也。一手持二秉曰「兼」。三画之卦象三才，三才各一而已。一而不两，则独而无对，天独阳而无阴，地独阴而无阳，人之阴阳亦混而不分，必皆兼而两之，天、人地各有阴阳，然后其道全而不偏，所以重三画之卦而为六画者，此也。有六画，则初、二为「地道」，三、四为「人道」，五、上为「天道」，各两其一而为六，六者非有他也，以三才之道各有阴阳也。 道有变动，故曰爻，爻有等，故曰物，物相杂，故曰文，文不当，故吉凶生焉。 「道」，即上文所谓「天道」、「人道」、「地道」也。「有变动」，谓卦位之为天、为人、为地者，有更变移动也。三画之卦重为六画，惟初为地道，上为天道，不改移，中四画皆有改移。二，人也，而为地。三，天也，而为人。四，地也，而为人。五，人也，而为天。故曰「道有变动」。阴位阳位交错相间，谓之「爻」。三画之卦不曰「爻」者，无阴阳相间也。既有六画，而三才之道改移其位，然后初为地之阳，二为地之阴，三为人之阳，四为人之阴，五为天之阳，上为天之阴，相交错而谓之爻也。等，如上章贵贱之等。各爻之画比并有不同，故曰有等。其有等不同者，或是奇画，则为阳物，或是耦画，则为阴物也。二物相杂在六位之中，然后成文。若阴阳纯而不杂，则不文矣。文不当，谓阳物居阴位，阴物居阳位，当位者多吉，不当位者多凶，吉凶由当不当而生，不言当而但言不当者，省文自可见意也。</p><p>传六之七章，凡六十六字注覆，孚后切。间，居限切，下同。省文，所梗切。 易之兴也，其当殷之末世、周之盛德邪？当文王与纣之事邪？ 殷之末世，谓纣。周之盛德，谓文王。因第四章之起语而申言之，彼但言其时，此并言其人也。此卒章之第一节。 是故其辞危。危者使平，易者使倾，其道甚大，百物不废，惧以终始，其要无咎，此之谓易之道也。 是故以下，终第一节之意。危者，惧而不敢安也。易者，匆而不知惧也。文王以盛德遇末世而有忧患，故其系易也，有危惧之辞，盖谓人之处事，其心危惧则可保平康，其心匆易则必至倾覆。使者，理有必至，若或使之云尔。前篇以「易则易知」言乾之善，此章又以「易者使倾」言人之恶。易知之易，敬胜怠而其心易直也；使倾之易，怠敬胜而其心匆易也。字虽同而其意正相反。「其道」，谓作易之道。物，犹事也。不废，谓具备于中而无所弃遗也。易之道，虽无一事不该，然不过欲人于每事自始至终以危惧之心处之，其指归欲人之无咎而已。易有彖辞，有爻辞，而所谓「其辞危」者，乃专以文王彖辞言，何也？盖系辞自文王始，周公不过补文王之未及为者尔，无异旨也。父统子叶，但言彖辞，而爻辞在其中矣。下文则皆兼彖、爻之义而言也。 夫乾，天下之至健也，德行恒易以知险。夫坤，天下之至顺也，德行恒简以知阻。能说诸心，能研诸虑，定天下之吉凶，成天下之亹亹者， 言圣人作易之道，本乎天地也。乾坤谓天地，非卦名也。天之健，地之顺，造化流行，常易常简，无有繁难也，又岂有妨害之者？而天地犹且知险知阻，人事则不无妨害之虞，其可匆易而不危惧乎？天地之知险知阻，非如人之知也。天之下，凡有险陷之处，天皆临而照之，是天下之险，天无一不知也。地之上凡有阻碍之处，地皆载而有之，是地上之阻，地无一不知也。作易圣人能如天之知险，故凡可以陷害于人者，必为之指示，以通其志，使人皆灼见，则其心开释而说怿。能如地之知阻，故凡可以妨碍于人者，必为之处置，以成其务，使人皆慎行，则其虑精审而研核定其所占之如是则吉，如是则凶，使人之于事无疑有决，而勉勉为之也。此第二节。 是故变化云为，吉事有祥，象事知器，占事知来。天地设位，圣人成能，人谋鬼谋，百姓与能。 「是故」以下，终第二节之意。「云为」，言动也。人能以易中阴阳变化之道，而用之以言，用之以动，则于事皆可以旨而有祥，必不至于凶而有灾也。或有所象之事，则能知器之形，而可以制器；或有所占之事，则能知未来之吉凶，而可以决疑。易之用，惟此四者而已。「云为」、「象占」，即上篇所谓「以言」、「以动」、「以制器」、「以卜筮」也。此四者，皆圣人本诸天地之道以教人者。故「天地设位于上下」，虽有此道，而不能使悉由此道。圣人作易，教人由此道，所以成天地之能也。「成」，谓有所阙而完足之。「鬼谋」，谓觋巫。「与」，如中庸「可以与知焉」之「与」。「人谋」，羲文之易，而用之以占。凡有一事，既谋之于人，又谋之于鬼，而后为之，则所为皆合易道之教，虽其愚不肖，亦可以与圣人之能也。健顺易简，知险知阻，此天地之能。说心研虑，定吉凶，成亹亹，此圣人之能，而成天地之能也。云「为之祥」，象占之知，此百姓之能，而与圣人之能者也。 八卦以象告，爻彖以情言。刚柔杂居，而吉凶可见矣。变动以利言，吉凶以情迁。 八卦，谓六爻、四象之上下二体也。项氏曰：「八卦以象告」，谓卦之以四象示人。「爻彖以情言」，谓辞之以言谕人也。「刚柔杂居而吉凶可见」，再言象之所以示人者明也。「变动以利言，吉凶以情迁」，再言辞之所以谕人者殊也。自彖辞观之，卦体本以变动而成，故彖辞专言其变动之利，如「柔来而文刚」，「分刚上而文柔」之类是也。虽睽、蹇、明夷至不美之卦，其彖皆有所利，盖类变而成卦，则以成卦者为利，故曰「变动以利言」。自爻辞观之，据逐爻之情而处事，则吉凶皆异于本彖矣。故有在彖为主爻，而在本爻则为凶者，如震之九四，「震惊百里」，可为祭主，而在本爻则为「泥而未光」之类是也。故曰「吉凶以情迁」，观彖之本辞，则为迁易也。澄谓：「变动即第五章所谓变动不居者，言卦画之更变移动其位也。爻彖以情言，彖与爻皆言情也。吉凶以情迁，则情专属爻而不及彖，何也？盖变动以利言，利亦自情而生也。彖亦有情，爻亦有利，互文也。」此第三节。 是故爱恶相攻而吉凶生，远近相取而悔吝生，情伪相感而利害生。凡易之情，近而不相得则凶；或害之，悔且吝。 「是故」以下至篇终，皆终第三节之意。「爱恶」者，情也。「相攻」，谓相爱两相恶也。「远」，谓应；「近」，谓比。「相取」，谓远取远、近取近也。情之真者曰情，情之非真者曰「伪」。「相感」，谓情感情、伪感伪也。爱恶远近皆有情伪，或以情相取，或以伪相取。情伪皆有爱恶，其相爱或真或伪，其相恶亦或真或伪。伪者，情之反；害者，利之反。凡占曰「不利」、「无攸利」者，害也。项氏曰：「自此以下，皆言吉凶以情迁之事。以六爻吉凶悔吝之三辞，分出于相攻、相取、相感之三情，而总属于相近之一情。四相者，爻之情也。命辞之法，必各象其爻之情，故观其辞可以知其情。利害者，商略其事宜，有利有不利也。悔吝则有迹矣，言凶则其成也，故总而名之曰吉凶。」「相感」者，情之始交，故以「利害」言之；「相取」则有事矣，故以「悔吝」言之；「相攻」则其事极矣，故以「吉凶」言之。「远近」「情伪」，姑就浅深分之，若错而总之，则「相攻」「相取」「相感」之人，其意皆有远近，其行皆有情伪，其情皆有爱恶也，故总以「相近」一条明之。「近而不相得」，则以「恶相攻」而凶生矣，以「伪相感」而害生矣，不以「近相取」而悔吝生矣，是则一近之中备此三条也。凡爻有比爻，有应爻，有一卦之主爻，皆情之当相得者也。凡称近者，止据比爻言之，反以三隅，则远而为应为主者，亦必备此三条矣。但居之近者，其吉凶尤多，故圣人槩以「近」者明之。近而不相得，则恶相攻、伪相感；近不相取则爱相攻、情相感，而近取者为相得矣。不相得则凶害悔吝，其相得则吉利悔亡，无悔无咎，从可知也。夫子之己言者三，其未言者三，总之凡六条。然此据近之比爻言尔，若远之应爻及主爻，亦当各备六条，总之为十八条矣。尝以此十八条之例考之爻辞皆合，乃知作传圣人以此该括易之辞情，至为精密。而诸家注释，唯项氏能究其底蕴焉。 将叛者其辞惭，中心疑者其辞枝，吉人之辞寡，躁人之辞多，诬善之人其辞游，失其守者其辞屈。 上章言易之辞皆由情而生，此又以人譬之。人之辞亦由情而生也。将欲倍畔，犹未发露，中有所慊，唯恐为人所觉，故其辞惭怍；中心疑惑，不能剖决，意谓如此又恐不如此，故其辞如木之枝，两闲端岐，不敢执一。吉人静重深厚，故其辞谨而简；躁人轻动浅薄，故其辞易而繁；诬毁善人自知非实，故其辞浮游不定；困阨沮丧，失所操守，故其辞卑屈不伸。叛、疑、吉、躁、诬、失者，人之六情有不同，故惭、枝、寡、多、游、屈，其六辞各因其情而不同焉。朱子曰：卦爻之辞亦犹是也。澄案：此篇之首章，泛言辞变象占四道，而末句归重于辞，且以本于圣人之情。至此卒章凡三节，其中亦言四道，而首末皆言彖爻之辞，末又本于易之情，以终繋辞之传。盖唯圣人之情能知易之情而系易之辞也。是为一篇始终之脉络云。</p><p>传六之八章，凡二百五十四字。「研诸」下，旧本有「侯之」二字，案王氏略例无之。晁氏曰：「王昭素、司马温公皆以为衍字。」易者，恒易，以豉切。要，一遥切。夫，音扶。行，下孟切。说，音曰。与能，音预。恶，乌路切。注「必为之」，云伪切。与，如字。与知之与、与于而与，并音预。比，皮二切。系辞传上下篇，共二十章，章首发端以天地字者三，以圣人字者二，以易字者卜一，以彖爻，以一阴一阳，以八卦，以阳卦、阴卦者各一。旧本有「子曰」者六，先儒以为后人所加。今考之，「易，其至矣乎！知变化之道者，其知神之所为乎？」皆是前章之结语，后之分章者欲以此为后章之起语。「书不尽言」，「乾坤其易之门邪」，皆是连上文「共」为一章，后之分章者欲分截自此别为一章，故四处各加「子曰」字以别之。易有圣人之道四马者，是再提章首起句为结句，圣人立象以尽意，是以答语答上文问语，故两处亦各加「子曰」字，今并删去，庶俾读者不致生疑，而妄谓系辞传非夫子所作云。 易纂言卷八。</p>',12)])])}const h=e(n,[["render",r]]);export{f as __pageData,h as default};
